template<>
std::array<CVA6_DSE_MAPExplorer<false>::DVecType, 1024>
CVA6_DSE_MAPExplorer<false>::delayVectors =
    buildDelayVectors<false>();

template<>
std::array<CVA6_DSE_MAPExplorer<false>::CombType, 16384>
CVA6_DSE_MAPExplorer<false>::combs =
    buildCombs<false>(CVA6_DSE_MAPExplorer<false>::delayVectors);

template<>
CVA6_DSE_MAPExplorer<false>::CVA6_DSE_MAPExplorer()
    : MAPExplorerBase<false>(
        &CVA6_DSE_blockDict,
        &CVA6_DSE_instrDict,
        resGroupLUT,
        resGroups,
        &branchGroup,
        delayVectors,
        combs) 
{}

template<>
void CVA6_DSE_MAPExplorer<false>::connectChannel(Channel* channel_){
    ch_instrCnt_ptr = &(channel_->instrCnt);
    ch_typeId_ptr = channel_->typeId;

    // TODO: Currently hard-coded. Need to get this information from somewhere
    CVA6_DSE_Channel* channel = static_cast<CVA6_DSE_Channel*>(channel_);
    ch_pc_ptr = channel->pc;
    ch_rs1_ptr = channel->rs1;
    ch_rs2_ptr = channel->rs2;
    ch_rd_ptr = channel->rd;

    branchGroup.connectChannel(channel_, &curInstrIdx);

    resGroups[0]->connectChannel(channel_, &curInstrIdx);
    resGroups[1]->connectChannel(channel_, &curInstrIdx);
    resGroups[2]->connectChannel(channel_, &curInstrIdx);
    resGroups[3]->connectChannel(channel_, &curInstrIdx);
}

